<script setup>
import { ref, reactive, computed, onMounted, onBeforeUnmount, watch, defineAsyncComponent } from 'vue'
import { showToast, showSuccessToast, showConfirmDialog, closeDialog } from 'vant'
import SectionStatus from './components/SectionStatus.vue'
import { createSectionLoader, createSessionRequests, resolveEpisodePlan } from './loading'
import { registerShellWorker } from './pwa'
import { api as rawApi, post as rawPost } from './api'
import { money, signed, tradePreview, beijingInput, backupSummary } from './display'

const PriceChart=defineAsyncComponent(()=>import('./components/PriceChart.vue'))
const loading=ref(true), startupError=ref(''), busy=ref(false), me=ref(null), account=ref(null), market=ref({points:[]}), plans=ref([]), episodes=ref([]), entries=ref([]), deliveries=ref([]), updateAvailable=ref(false)
const tab=ref('home'), popup=ref(''), authMode=ref('login'), entryPage=ref(1), entryCount=ref(0), admins=ref([]), system=ref(null), invite=ref(''), authError=ref('')
const credentials=reactive({username:'',password:'',code:''}), init=reactive({budget:'',cash:'',shares:'0',unit_cost:'0'}), settings=reactive({fee_rate:'',fee_minimum:'',fee_extra:'',reminder_minutes:30,reminder_max:3,push_token:''})
const form=reactive({}), entryKey=ref(''), cashForm=reactive({amount:'',reason:''}), passwords=reactive({old_password:'',new_password:''})
let timer
let shellWorker,bootstrapVersion=0
const requests=createSessionRequests({request:rawApi,submit:rawPost})
const api=(...args)=>requests.request(...args)
const post=(...args)=>requests.submit(...args)
const sectionState=reactive(Object.fromEntries(['account','market','plans','episodes','entries'].map(k=>[k,{pending:false,error:''}])))
const sections={
  account:{state:sectionState.account,load:opts=>api('/account/',opts),apply:v=>{account.value=v},clear:()=>{account.value=null}},
  market:{state:sectionState.market,load:opts=>api('/market/',opts),apply:v=>{market.value=v},clear:()=>{market.value={points:[]}}},
  plans:{state:sectionState.plans,load:opts=>api('/plans/',opts),apply:v=>{plans.value=v},clear:()=>{plans.value=[]}},
  episodes:{state:sectionState.episodes,load:opts=>api('/episodes/',opts),apply:v=>{episodes.value=v},clear:()=>{episodes.value=[]}},
  entries:{state:sectionState.entries,load:opts=>api(`/entries/?page=${entryPage.value}`,opts),apply:v=>{entries.value=v.results;entryCount.value=v.count},clear:()=>{entries.value=[];entryCount.value=0}},
}
const loader=createSectionLoader({sections,onUnauthorized(){requests.invalidate();me.value=null;clearPrivateForms();showToast('登录已过期或账号已停用，请重新登录')}})
function clearPrivateForms(){closeDialog();popup.value='';deliveries.value=[];admins.value=[];system.value=null;invite.value='';Object.keys(form).forEach(k=>delete form[k]);Object.assign(settings,{fee_rate:'',fee_minimum:'',fee_extra:'',reminder_minutes:30,reminder_max:3,push_token:'',token_bound:false});Object.assign(init,{budget:'',cash:'',shares:'0',unit_cost:'0'});cashForm.amount='';cashForm.reason='';passwords.old_password='';passwords.new_password='';credentials.password='';entryPage.value=1;tab.value='home'}
function resetPrivate(){requests.invalidate();loader.reset();clearPrivateForms()}
const activePlans=computed(()=>plans.value.filter(p=>p.status==='ACTIVE'))
const price=computed(()=>market.value.quote?.price)
const pnlClass=v=>Number(v)>0?'gain':Number(v)<0?'loss':''
const fmtTime=v=>v?new Date(v).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):'暂无'
const initialized=computed(()=>!!account.value?.initialized_at)
const liveEpisodes=computed(()=>episodes.value.filter(e=>['OPEN','UNKNOWN'].includes(e.status)))
async function action(fn) { if(busy.value)return;busy.value=true;try{await fn()}catch(e){if(e!=='cancel'&&e!=='close'&&e.code!=='CANCELLED')showToast({message:e.message||'操作未完成，请重试',duration:4000})}finally{busy.value=false} }
function refresh({force=false}={}) {
  if (!me.value) return
  const keys=force?['account','market','plans','episodes','entries']:tab.value==='history'?['account','entries']:tab.value==='plans'?['account','plans']:['account','market','plans','episodes']
  for(const key of keys)void loader.run(key,{force})
}
async function bootstrap(){const version=++bootstrapVersion;loading.value=true;startupError.value='';try{const [,user]=await Promise.all([api('/auth/csrf/'),api('/me/')]);if(version!==bootstrapVersion)return;resetPrivate();me.value=user;refresh()}catch(e){if(version!==bootstrapVersion)return;if(![401,403].includes(e.status))startupError.value=e.message;me.value=null}finally{if(version===bootstrapVersion)loading.value=false}}
async function authenticate(){await action(async()=>{authError.value='';await api('/auth/csrf/');await post(`/auth/${authMode.value}/`,credentials);const user=await api('/me/');resetPrivate();me.value=user;refresh()})}
async function initialize(){await action(async()=>{account.value=await post('/account/initialize/',init);refresh({force:true});showSuccessToast('已建立期初账本')})}
function openEpisode(e){const plan=resolveEpisodePlan(e,plans.value);if(!plan){showToast('计划尚未就绪或已变化，请刷新后确认');void loader.run('plans',{force:true});return}openTrade(e.side,plan)}
function openPlan(side,p=null){if(!initialized.value){showToast('请先完成账本初始化');return}Object.keys(form).forEach(k=>delete form[k]);Object.assign(form,p?{...p}:{side,direction:'BELOW',target_price:'',target_profit:'',amount:'',quantity:'',sell_all:false});popup.value='plan'}
function planBody(){return{side:form.side,direction:form.direction,target_price:form.target_price||null,target_profit:form.side==='SELL'&&form.target_profit!==''&&form.target_profit!=null?form.target_profit:null,amount:form.side==='BUY'?form.amount:null,quantity:form.side==='SELL'&&!form.sell_all?form.quantity:null,sell_all:form.side==='SELL'&&form.sell_all}}
async function savePlan(){await action(async()=>{if(price.value&&((form.side==='BUY'&&(form.direction==='BELOW'?Number(price.value)<=Number(form.target_price):Number(price.value)>=Number(form.target_price)))||(form.side==='SELL'&&form.target_price&&Number(price.value)>=Number(form.target_price))))await showConfirmDialog({title:'当前参考价已达到价格条件',message:'保存后会在交易时段按有效行情和账户状态检查，可能很快触发提醒。'});if(form.id)await api(`/plans/${form.id}/`,{method:'PATCH',body:planBody()});else await post('/plans/',planBody());popup.value='';await refresh({force:true});showSuccessToast('计划已保存')})}
async function cancelPlan(p){await action(async()=>{await showConfirmDialog({title:'取消这条计划？',message:'取消后停止监测，账目不受影响。'});await post(`/plans/${p.id}/cancel/`,{});await refresh({force:true})})}
function openTrade(side='BUY',p=null,correction=null){if(!initialized.value){showToast('账户尚未就绪，请先重试加载账户');return}Object.keys(form).forEach(k=>delete form[k]);const payload=correction?.payload;Object.assign(form,{side:payload?.side||side,quantity:payload?.quantity|| (p?.side==='SELL'?(p.sell_all?account.value.shares:p.quantity):100),price:payload?.price||price.value||'',fee:payload?.fee??'',occurred_at:payload?.occurred_at?localInput(payload.occurred_at):localInput(new Date()),plan_id:p?.id,plan_version:p?.version,correction:correction?.id,reason:''});entryKey.value=crypto.randomUUID();popup.value='trade'}
function localInput(v){return beijingInput(v)}
function estimateFee(){if(settings.fee_rate===''||settings.fee_minimum===''||settings.fee_extra===''){showToast('请先在设置填写券商费用参数');return}form.fee=(Math.max(Number(settings.fee_minimum),Number(form.price)*Number(form.quantity)*Number(settings.fee_rate))+Number(settings.fee_extra)).toFixed(2)}
async function saveTrade(){await action(async()=>{await showConfirmDialog({title:form.correction?'确认纠错并重算？':'确认实际成交',message:`${tradePreview(form)}\n请以券商成交记录为准。`});const t={side:form.side,quantity:form.quantity,price:form.price,fee:form.fee,occurred_at:`${form.occurred_at}+08:00`};if(form.plan_id){t.plan_id=form.plan_id;t.plan_version=form.plan_version}if(form.correction)await post(`/entries/${form.correction}/correct/`,{reason:form.reason,replacement:t},entryKey.value);else await post('/entries/',t,entryKey.value);popup.value='';await refresh({force:true});showSuccessToast('已入账')})}
function openCash(){cashForm.amount='';cashForm.reason='';entryKey.value=crypto.randomUUID();popup.value='cash'}
async function saveCash(){await action(async()=>{await post('/cash/',cashForm,entryKey.value);popup.value='';await refresh({force:true});showSuccessToast('资金变动已记录')})}
async function ignore(e){await action(async()=>{await post(`/episodes/${e.id}/ignore/`,{});await refresh({force:true});showToast('本轮提醒已停止，计划继续保留')})}
async function openSettings(){await action(async()=>{const s=await api('/settings/');Object.assign(settings,s,{push_token:''});deliveries.value=await api('/deliveries/');popup.value='settings'})}
async function saveSettings(){await action(async()=>{const body={...settings};delete body.token_bound;if(!body.push_token)delete body.push_token;for(const k of ['fee_rate','fee_minimum','fee_extra'])if(body[k]==='')body[k]=null;await api('/settings/',{method:'PATCH',body});me.value=await api('/me/');showSuccessToast('设置已保存')})}
async function removeToken(){await action(async()=>{await api('/settings/',{method:'PATCH',body:{push_token:''}});settings.token_bound=false;showToast('已解除绑定')})}
async function testPush(){await action(async()=>{await showConfirmDialog({title:'向自己的微信发送测试？',message:'请先保存密钥；本次将实际调用 PushPlus。'});const r=await post('/settings/test-push/',{});showToast(r.detail);deliveries.value=await api('/deliveries/')})}
async function changePassword(){await action(async()=>{await post('/auth/password/',passwords);passwords.old_password='';passwords.new_password='';showSuccessToast('密码已更新')})}
async function logout(){await action(async()=>{await post('/auth/logout/',{});bootstrapVersion++;resetPrivate();me.value=null})}
async function openAdmin(){await action(async()=>{[admins.value,system.value]=await Promise.all([api('/admin/users/'),api('/admin/system/')]);popup.value='admin'})}
async function newInvite(){await action(async()=>{invite.value=(await post('/admin/invites/',{})).code})}
async function toggleUser(u){await action(async()=>{await api(`/admin/users/${u.id}/`,{method:'PATCH',body:{is_active:!u.is_active}});admins.value=await api('/admin/users/')})}
async function budget(){await action(async()=>{Object.keys(form).forEach(k=>delete form[k]);form.budget=account.value.budget;popup.value='budget'})}
async function saveBudget(){await action(async()=>{await api('/account/',{method:'PATCH',body:{budget:form.budget}});popup.value='';await refresh({force:true})})}
async function changePage(p){entryPage.value=p;await loader.run('entries',{force:true})}
function onVisible(){if(document.visibilityState==='visible'){if(me.value)refresh();else if(startupError.value&&!loading.value)void bootstrap();shellWorker?.check()}}
function onOnline(){if(me.value)refresh();else if(!loading.value)void bootstrap()}
function applyUpdate(){if(!popup.value&&!busy.value)shellWorker?.activate()}
watch(tab,()=>refresh())
onMounted(()=>{shellWorker=registerShellWorker(()=>{updateAvailable.value=true});void bootstrap();timer=setInterval(()=>{if(document.visibilityState==='visible')refresh()},30000);document.addEventListener('visibilitychange',onVisible);window.addEventListener('online',onOnline)})
onBeforeUnmount(()=>{bootstrapVersion++;loader.reset();shellWorker?.dispose();clearInterval(timer);document.removeEventListener('visibilitychange',onVisible);window.removeEventListener('online',onOnline)})
</script>

<template>
  <main v-if="loading || (!me && startupError)" class="startup-shell">
    <div class="brand"><span class="brand-small">金</span><strong>金笺</strong></div>
    <template v-if="loading"><p class="muted">正在连接你的账本…</p><section class="card"><van-skeleton title :row="4" /></section><section class="card"><van-skeleton title :row="3" /></section></template>
    <section v-else class="card startup-error"><h2>暂时无法连接账本</h2><p class="muted">{{startupError}}</p><p class="hint">页面可以打开，但登录、最新行情和记账需要连接服务器。不会离线提交成交。</p><van-button block round type="primary" @click="bootstrap">重新连接</van-button></section>
  </main>
  <main v-else-if="!me" class="auth-shell">
    <div class="brand-mark">金</div><p class="eyebrow">GOLD · SIMPLE · PERSONAL</p><h1>金笺</h1><p class="auth-intro">一份清楚的黄金账本<br>在你关心的价格，提醒你。</p>
    <section class="card auth-card"><h2>{{authMode==='login'?'欢迎回来':'使用邀请加入'}}</h2><van-form @submit="authenticate">
      <van-field v-if="authMode==='register'" v-model="credentials.code" label="邀请码" placeholder="由管理员提供" required />
      <van-field v-model="credentials.username" label="用户名" autocomplete="username" required :rules="[{required:true,message:'请输入用户名'}]" />
      <van-field v-model="credentials.password" type="password" label="密码" :autocomplete="authMode==='login'?'current-password':'new-password'" required :rules="[{required:true,message:'请输入密码'}]" />
      <p v-if="authMode==='register'" class="hint">密码至少 10 位，避免常用或纯数字密码。</p><p v-if="authError" class="danger">{{authError}}</p>
      <van-button block round type="primary" native-type="submit" :loading="busy">{{authMode==='login'?'登录':'创建我的账号'}}</van-button>
    </van-form><button class="text-button auth-switch" @click="authMode=authMode==='login'?'register':'login'">{{authMode==='login'?'有邀请码？创建账号':'已有账号，返回登录'}}</button></section>
    <p class="footnote">仅关注 518880 · 自己决策，自己成交<br>忘记密码可联系 NAS 维护者协助恢复。</p>
  </main>
  <div v-else class="app-shell">
    <header class="topbar"><div class="brand"><span class="brand-small">金</span><div><strong>金笺</strong><span>黄金 ETF · 518880</span></div></div><button class="avatar" aria-label="个人设置" @click="openSettings">{{me.username.slice(0,1).toUpperCase()}}</button></header>
    <main class="content">
      <div v-if="updateAvailable && !popup && !busy" class="update-banner" role="status"><span>有新版页面可用</span><button class="text-button" @click="applyUpdate">更新页面</button></div>
      <section v-if="!account" class="card account-pending"><h2>我的账本</h2><SectionStatus :state="sectionState.account" label="账户" @retry="loader.run('account',{force:true})"/><van-skeleton v-if="sectionState.account.pending" :row="2" /></section>
      <section v-if="account && !initialized" class="card onboarding"><p class="eyebrow">第一步 · 建立自己的起点</p><h1>把现有资金记清楚</h1><p class="muted">只记录此刻的现金和持仓，不补造过去交易。没有持仓可填 0。</p><van-form @submit="initialize">
        <van-field v-model="init.budget" label="计划预算" type="number" placeholder="例如 20000" required /><van-field v-model="init.cash" label="可用现金" type="number" placeholder="实际可用金额" required /><van-field v-model="init.shares" label="现有份额" type="digit" required /><van-field v-model="init.unit_cost" label="每份成本" type="number" required />
        <van-button block round type="primary" native-type="submit" :loading="busy">建立账本</van-button></van-form><p class="hint">预算用于安排计划，不会自动增加可用现金。成本请参考券商记录。</p></section>
      <template v-else>
        <template v-if="tab==='home'">
          <div class="page-heading"><div><p class="eyebrow">照看黄金，也照顾节奏</p><h1>我的黄金</h1></div><span class="status-pill" :class="market.fresh?'online':''"><i></i>{{market.fresh?'行情有效':market.session_open?'行情待更新':'休市 / 非交易时段'}}</span></div>
          <section class="card price-card"><SectionStatus :state="sectionState.market" label="行情" @retry="loader.run('market',{force:true})"/><div class="row"><span class="muted">华安黄金 ETF <small>518880</small></span><span class="tiny">{{market.quote?.source||'暂无来源'}}</span></div><div class="price-row"><strong class="price">{{price?Number(price).toFixed(3):'—'}}<small>元</small></strong><span v-if="market.change_percent!=null" class="change" :class="pnlClass(market.change_percent)">{{signed(market.change_percent)}}%</span></div><p class="tiny">源数据时间 {{fmtTime(market.quote?.source_at)}}</p>
            <div class="chart-caption"><strong>今日分时</strong><span>{{market.curve_date||'—'}} · 北京时间</span></div><PriceChart v-if="market.points.length" :points="market.points" /><div v-else class="chart-empty"><van-icon name="chart-trending-o" size="30"/><span>今日曲线还在等待数据</span><small>收到有效行情后显示，不补画缺失区间</small></div><p class="hint curve-note">{{market.curve_note||'显示已取得的数据，缺口留空；采样不保证捕获每次瞬间到价。'}}</p>
            <div v-if="!market.fresh" class="subtle-notice">{{market.message||'行情尚未就绪，到价提醒暂停。记账仍可使用。'}}</div>
          </section>
          <SectionStatus :state="sectionState.episodes" label="提醒" @retry="loader.run('episodes',{force:true})"/><section v-if="liveEpisodes.length" class="alert-stack"><article v-for="e in liveEpisodes" :key="e.id" class="card alert-card"><div class="row"><strong>{{e.side==='BUY'?'买入':'卖出'}}条件已达到</strong><span class="status-pill">{{e.status==='UNKNOWN'?'推送结果未确认':'待处理'}}</span></div><p>{{e.context.reason}} · 参考价 {{e.context.price}}</p><div class="button-row"><van-button size="small" type="primary" round :disabled="!resolveEpisodePlan(e,plans)" @click="openEpisode(e)">确认实际成交</van-button><van-button size="small" plain round @click="ignore(e)">暂不操作</van-button></div></article></section>
          <section v-if="initialized" class="card account-card"><SectionStatus :state="sectionState.account" label="账户" @retry="loader.run('account',{force:true})"/><div class="row"><h2>我的持仓</h2><span class="tiny">截至当前记录</span></div><div class="holding-main"><div><span class="muted">持有份额</span><strong>{{account.shares.toLocaleString()}}<small>份</small></strong></div><div><span class="muted">每份成本</span><strong>{{account.unit_cost==null?'—':Number(account.unit_cost).toFixed(4)}}<small>元</small></strong></div></div><div class="metrics"><div><span>可用现金</span><strong>¥{{money(account.cash)}}</strong></div><div><span>持仓市值</span><strong>¥{{money(account.market_value)}}</strong></div><div><span>当前浮盈亏</span><strong :class="pnlClass(account.floating)">{{signed(account.floating)}}</strong></div><div><span>已记录累计净收益</span><strong :class="pnlClass(account.total_profit)">{{signed(account.total_profit)}}</strong></div></div><p class="hint">浮盈亏未扣未来卖出费用。收益自 {{fmtTime(account.initialized_at)}} 期初录入起算，不包含未录入的历史已卖出收益。行情过期时资产为最后行情估值。</p></section>
          <section class="card next-card"><SectionStatus :state="sectionState.plans" label="计划" @retry="loader.run('plans',{force:true})"/><div class="row"><h2>接下来的一笔</h2><button class="text-button" @click="tab='plans'">管理计划 →</button></div><p v-if="!activePlans.length && !sectionState.plans.pending && !sectionState.plans.error" class="muted">先写下自己关心的价格，剩下交给提醒。</p><div v-for="p in activePlans" :key="p.id" class="mini-plan"><span class="side-badge" :class="p.side==='SELL'?'sell':''">{{p.side==='BUY'?'买':'卖'}}</span><div><strong>{{p.side==='BUY'?(p.direction==='BELOW'?'跌到':'涨到'):'涨到'}} {{p.target_price||'收益目标'}}</strong><p>{{p.side==='BUY'?`含费上限 ¥${money(p.amount)}`:p.sell_all?'卖出全部持仓':`卖出 ${p.quantity} 份`}}</p></div><span class="tiny">监测中</span></div></section>
        </template>
        <template v-if="tab==='plans' && initialized"><SectionStatus :state="sectionState.plans" label="计划" @retry="loader.run('plans',{force:true})"/><SectionStatus :state="sectionState.account" label="账户" @retry="loader.run('account',{force:true})"/><div class="page-heading"><div><p class="eyebrow">把想法写下来</p><h1>购买计划</h1></div></div><section class="card budget-card"><div><span class="muted">计划预算</span><strong>¥{{money(account.budget)}}</strong></div><button class="text-button" @click="budget">修改</button><p class="hint">现金 ¥{{money(account.cash)}} · 当前成本占用 ¥{{money(account.cost_basis)}}<br>预算剩余额度按预算减持仓成本估算，不代表现金。</p></section>
          <section v-for="side in ['BUY','SELL']" :key="side" class="card plan-card"><div class="row"><h2>{{side==='BUY'?'下一笔买入':'下一笔卖出'}}</h2><span class="side-badge" :class="side==='SELL'?'sell':''">{{side==='BUY'?'买':'卖'}}</span></div><template v-if="activePlans.find(p=>p.side===side)"><template v-for="p in activePlans.filter(p=>p.side===side)" :key="p.id"><div class="plan-target"><small>{{side==='BUY'?(p.direction==='BELOW'?'价格跌到或低于':'价格涨到或高于'):'目标价 / 本笔目标净收益率'}}</small><strong>{{p.target_price?`¥${p.target_price}`:'—'}}<span v-if="side==='SELL'&&p.target_profit!=null"> / {{p.target_profit}}%</span></strong></div><p class="muted">{{side==='BUY'?`含费金额上限 ¥${money(p.amount)}`:p.sell_all?'全部持仓':`${p.quantity} 份`}}</p><p class="hint">{{p.evaluation?.reason}}<template v-if="p.evaluation?.quantity"> · 参考 {{p.evaluation.quantity}} 份</template></p><div class="button-row"><van-button size="small" round type="primary" @click="openTrade(side,p)">已实际成交</van-button><van-button size="small" round plain @click="openPlan(side,p)">编辑</van-button><button class="text-button muted" @click="cancelPlan(p)">取消计划</button></div></template></template><template v-else-if="!sectionState.plans.pending && !sectionState.plans.error"><p class="empty-text">{{side==='BUY'?'安排下一笔，按自己的节奏积累。':'设置你愿意卖出的价格或净收益。'}}</p><van-button round block plain @click="openPlan(side)">＋ {{side==='BUY'?'添加买入计划':'添加卖出计划'}}</van-button></template><p class="hint">{{side==='BUY'?'计划跨天保留；不会自动下单。':'目标价与净收益率任一满足，且预计扣费后不亏损，才提醒。'}}</p></section>
        </template>
        <template v-if="tab==='history' && initialized"><SectionStatus :state="sectionState.entries" label="记录" @retry="loader.run('entries',{force:true})"/><SectionStatus :state="sectionState.account" label="账户" @retry="loader.run('account',{force:true})"/><div class="page-heading"><div><p class="eyebrow">每一笔，都有来处</p><h1>交易记录</h1></div><button class="text-button" @click="openCash">资金变动</button></div><div class="button-row history-actions"><van-button round type="primary" @click="openTrade('BUY')">记一笔买入</van-button><van-button round plain @click="openTrade('SELL')">记一笔卖出</van-button></div><section class="card"><div class="row"><h2>已记录卖出净收益</h2><strong :class="pnlClass(account.realized)">{{signed(account.realized)}}</strong></div><p class="hint">按记账顺序计算移动平均成本；成交时间是记录信息。补录更早交易请核对顺序。纠错保留原记录并重算。</p></section><section class="card entries"><div v-for="e in entries" :key="e.id" class="entry-row"><div class="row"><div class="entry-title"><span class="side-badge" :class="e.payload.side==='SELL'?'sell':''">{{e.kind==='TRADE'?(e.payload.side==='BUY'?'买':'卖'):e.kind==='CASH'?'资':'改'}}</span><strong>{{e.kind==='TRADE'?(e.payload.side==='BUY'?'买入':'卖出')+' 518880':e.kind==='CASH'?'资金变动':'账目纠错'}}</strong></div><strong>{{e.kind==='TRADE'?`${e.payload.quantity} 份`:e.kind==='CASH'?signed(e.payload.amount):`#${e.corrects}`}}</strong></div><p v-if="e.kind==='TRADE'">成交价 ¥{{e.payload.price}} · 手续费 ¥{{money(e.payload.fee)}}</p><p v-if="e.reason">{{e.reason}}</p><div class="row"><span class="tiny">{{fmtTime(e.payload.occurred_at||e.created_at)}}<template v-if="e.corrected"> · 已有纠错</template></span><button v-if="e.kind==='TRADE'" class="text-button" @click="openTrade(e.payload.side,null,{...e,payload:e.effective_payload||e.payload})">纠错</button><button v-if="e.kind==='CASH'" class="text-button" @click="openCash">以反向流水修正</button></div></div><van-empty v-if="!entries.length && !sectionState.entries.pending && !sectionState.entries.error" description="还没有成交记录" :image-size="70"/><van-pagination v-if="entryCount>20" :model-value="entryPage" :total-items="entryCount" :items-per-page="20" mode="simple" @change="changePage"/></section><section class="card initial-card"><h2>期初快照</h2><p class="muted">现金 ¥{{money(account.initial_cash)}} · {{account.initial_shares}} 份<br>初始持仓成本 ¥{{money(account.initial_cost)}}</p><p class="tiny">{{fmtTime(account.initialized_at)}} 建立，不作为历史成交。</p></section></template>
      </template>
      <footer class="page-footer">按自己的计划，慢慢来。<br><span>仅做提醒与记账，实际交易以券商记录为准。</span></footer>
    </main>
    <van-tabbar v-model="tab" active-color="#936d28" inactive-color="#97968e" safe-area-inset-bottom><van-tabbar-item name="home" icon="home-o">首页</van-tabbar-item><van-tabbar-item :disabled="!initialized" name="plans" icon="todo-list-o">计划</van-tabbar-item><van-tabbar-item :disabled="!initialized" name="history" icon="records-o">记录</van-tabbar-item></van-tabbar>
  </div>

  <van-popup :show="!!popup" position="bottom" round closeable :close-on-click-overlay="!busy" @update:show="v=>{if(!v&&!busy)popup=''}" class="form-popup" safe-area-inset-bottom>
    <template v-if="popup==='plan'"><h2>{{form.id?'编辑':'添加'}}{{form.side==='BUY'?'买入':'卖出'}}计划</h2><van-form @submit="savePlan"><van-field v-if="form.side==='BUY'" label="买入方向"><template #input><van-radio-group v-model="form.direction" direction="horizontal"><van-radio name="BELOW">跌到买</van-radio><van-radio name="ABOVE">涨到买</van-radio></van-radio-group></template></van-field><van-field v-model="form.target_price" label="目标价格" type="number" placeholder="精确到 0.001 元" :required="form.side==='BUY'"/><van-field v-if="form.side==='BUY'" v-model="form.amount" label="含费金额上限" type="number" required/><template v-else><van-field v-model="form.target_profit" label="本笔净收益率" type="number" placeholder="例如 5，表示 5%"><template #right-icon>%</template></van-field><p class="hint">目标价、净收益率至少填一项；都填时任一达标即可，但预计扣费后须不亏损。</p><van-cell title="卖出全部持仓"><template #right-icon><van-switch v-model="form.sell_all" size="22"/></template></van-cell><van-field v-if="!form.sell_all" v-model="form.quantity" label="卖出份额" type="digit" required/></template><van-button block round type="primary" native-type="submit" :loading="busy">保存计划</van-button></van-form></template>
    <template v-if="popup==='trade'"><h2>{{form.correction?'纠正成交记录':'确认实际成交'}}</h2><p class="hint">填写券商实际成交数据。手动录入允许记录实际发生的亏损卖出。</p><van-form @submit="saveTrade"><van-field label="买卖方向"><template #input><van-radio-group v-model="form.side" direction="horizontal" :disabled="!!form.plan_id"><van-radio name="BUY">买入</van-radio><van-radio name="SELL">卖出</van-radio></van-radio-group></template></van-field><van-field v-model="form.price" label="实际价格" type="number" required/><van-field v-model="form.quantity" label="实际份额" type="digit" required/><van-field v-model="form.fee" label="实际手续费" type="number" required placeholder="可填 0，但不可留空"><template #button><button type="button" class="text-button" @click="estimateFee">按设置估算</button></template></van-field><van-field v-model="form.occurred_at" type="datetime-local" label="成交时间" required/><p class="hint">北京时间；更早补录按记账顺序计算，请核对成本。</p><van-field v-if="form.correction" v-model="form.reason" label="纠错原因" required/><div class="preview">{{tradePreview(form)}}</div><van-button block round type="primary" native-type="submit" :loading="busy">{{form.correction?'保留原记录并纠错':'核对无误，确认入账'}}</van-button></van-form></template>
    <template v-if="popup==='cash'"><h2>记录资金变动</h2><p class="hint">转入填正数，取出填负数；修正错误资金流水时写明原流水编号。不会改变投资预算。</p><van-form @submit="saveCash"><van-field v-model="cashForm.amount" label="变动金额" type="text" inputmode="decimal" required/><van-field v-model="cashForm.reason" label="原因" required/><van-button block round type="primary" native-type="submit" :loading="busy">记录变动</van-button></van-form></template>
    <template v-if="popup==='budget'"><h2>调整计划预算</h2><p class="hint">调整预算不会增加或减少可用现金。</p><van-form @submit="saveBudget"><van-field v-model="form.budget" label="计划预算" type="number" required/><van-button block round type="primary" native-type="submit" :loading="busy">保存预算</van-button></van-form></template>
    <template v-if="popup==='settings'"><p class="eyebrow">{{me.username}} · {{me.is_app_admin?'应用管理员':'我的账号'}}</p><h2>个人设置</h2><van-form @submit="saveSettings"><h3>券商费用估算</h3><p class="hint">费率用小数表示：万分之 0.5 填 0.00005。请按自己券商的 ETF 收费规则填写，未知时留空，系统暂停相关到价提醒。</p><van-field v-model="settings.fee_rate" label="手续费率" type="number" placeholder="例如 0.00005"/><van-field v-model="settings.fee_minimum" label="最低收费 / 元" type="number" placeholder="无最低收费填 0"/><van-field v-model="settings.fee_extra" label="每笔额外费用" type="number" placeholder="没有请填 0"/><h3>微信提醒</h3><p class="hint">每人使用自己的 PushPlus 密钥并按服务要求实名认证。密钥只写入，不回显。</p><van-field v-model="settings.push_token" label="PushPlus 密钥" type="password" :placeholder="settings.token_bound?'已绑定；留空保持不变':'尚未绑定'" autocomplete="off"/><van-field v-model="settings.reminder_minutes" label="重复间隔 / 分钟" type="digit"/><van-field v-model="settings.reminder_max" label="每轮最多次数" type="digit"/><p class="hint">间隔 20–1440 分钟，每轮 1–10 次。跨天不会清零；暂不操作可停止本轮。</p><van-button block round type="primary" native-type="submit" :loading="busy">保存设置</van-button></van-form><div class="button-row"><van-button size="small" round plain @click="testPush" :loading="busy">向自己发送测试</van-button><button v-if="settings.token_bound" class="text-button" @click="removeToken">解除绑定</button></div><div v-if="deliveries.length" class="delivery-list"><h3>最近推送</h3><p v-for="d in deliveries.slice(0,5)" :key="d.id" class="hint">{{fmtTime(d.created_at)}} · {{d.label}}<br>{{d.detail}}</p></div><h3>修改密码</h3><van-form @submit="changePassword"><van-field v-model="passwords.old_password" type="password" label="当前密码" autocomplete="current-password" required/><van-field v-model="passwords.new_password" type="password" label="新密码" autocomplete="new-password" required/><van-button block round plain native-type="submit" :loading="busy">更新密码</van-button></van-form><van-cell v-if="me.is_app_admin" title="管理邀请码与账号" is-link @click="openAdmin"/><van-button block round plain @click="logout" :loading="busy">退出登录</van-button></template>
    <template v-if="popup==='admin'"><h2>应用管理</h2><p class="hint">此处仅管理加入和启停，不提供他人资金、密钥或代登录功能。</p><van-button round type="primary" @click="newInvite" :loading="busy">生成一次性邀请码</van-button><div v-if="invite" class="invite-box"><strong>{{invite}}</strong><p class="hint">有效期 7 天，仅显示本次，请复制给亲友。</p></div><h3>账号</h3><van-cell v-for="u in admins" :key="u.id" :title="u.username" :label="u.is_app_admin?'应用管理员':u.is_active?'正常使用':'已停用'"><template #right-icon><van-switch v-if="!u.is_app_admin" :model-value="u.is_active" size="22" @change="toggleUser(u)"/></template></van-cell><h3>系统运行</h3><p class="hint">监测进程 {{system?.worker_ok?'正常':'尚未就绪 / 心跳过期'}}<br>行情状态：{{system?.market?.message||'暂无'}}<br>备份状态：{{backupSummary(system?.backup)}}</p><p class="hint">整库备份及密码恢复由 NAS 维护者操作。备份不可通过应用管理下载。</p></template>
  </van-popup>
</template>
